import 'package:flutter/material.dart';
import '../../data/models/models.dart';

/// Parcours annuel CM1 : cours structurés et exercices corrigés par trimestre.
class Cm1CompletionScreen extends StatelessWidget {
 const Cm1CompletionScreen({super.key});
 static const _units=<_Unit>[
    _Unit('T1 • Français','Lecture analytique et vocabulaire','Pour comprendre un texte, je distingue les informations explicites et les informations que je déduis. Je relève les mots importants et j’explique le sens d’un mot grâce au contexte.\n\nPour analyser, je formule le sujet en une phrase, puis je repère les paragraphes et leurs idées principales. Une information explicite est écrite directement ; une inférence se construit à partir de plusieurs indices. Je peux utiliser le dictionnaire pour vérifier le sens et chercher un synonyme ou un contraire.','« Le ciel s’assombrit, le vent se lève ; les enfants rentrent rapidement. » On comprend qu’un orage approche.','Quelle information peut-on déduire ?',['Le temps va probablement se dégrader','La journée commence','Les enfants vont nager'],0,'Le ciel sombre et le vent annoncent un mauvais temps.'),
    _Unit('T1 • Mathématiques','Grands nombres et opérations','Je lis les nombres par classes de trois chiffres. Pour poser une opération, j’aligne les unités de même rang et je vérifie le résultat par une opération inverse ou une estimation.\n\nJe maîtrise la valeur des chiffres jusqu’aux millions et je compare les nombres en examinant les classes de gauche à droite. Pour additionner ou soustraire, je vérifie les retenues. Pour multiplier, je décompose un facteur. Pour diviser, je vérifie que diviseur × quotient + reste redonne le dividende.','125 430 + 24 570 = 150 000.','Combien font 3 600 ÷ 9 ?',['40','400','4 000'],1,'3 600 ÷ 9 = 400.'),
    _Unit('T1 • Anglais','Présent simple et description','Le présent simple décrit les habitudes et les vérités générales. Avec he, she et it, on ajoute généralement -s ou -es au verbe. Les adjectifs décrivent les personnes et les objets.\n\nRéviser les pronoms personnels et les verbes courants : be, have, play, read, go, like. Construire une phrase affirmative, négative et interrogative. Utiliser des adjectifs simples (tall, kind, small, beautiful) et respecter l’ordre adjectif + nom.','My sister reads every evening. She is kind.','Choisis la bonne phrase.',['She play football.','She plays football.','She playing football.'],1,'Avec she, le verbe prend généralement -s : plays.'),
    _Unit('T1 • Sciences','Appareil digestif et nutrition','La digestion transforme les aliments en nutriments que le corps peut utiliser. Une alimentation variée, de l’eau potable et une bonne hygiène contribuent à la santé.\n\nLes aliments sont mastiqués dans la bouche, passent dans l’œsophage, puis dans l’estomac et l’intestin. La digestion les transforme ; les nutriments traversent la paroi intestinale et rejoignent le sang. Une alimentation équilibrée varie les aliments et limite l’excès de sucre, de sel et de matières grasses.','Les aliments passent par la bouche, l’œsophage, l’estomac puis l’intestin.','Quel est le rôle principal de la digestion ?',['Transformer les aliments pour le corps','Faire circuler l’air','Produire la lumière'],0,'La digestion transforme les aliments en éléments utilisables par l’organisme.'),
    _Unit('T1 • Éducation sociale','Histoire locale et repères géographiques','Une carte représente un espace vu de dessus. Le titre, la légende et l’orientation aident à la lire. Les repères historiques permettent de situer des événements dans le temps.\n\nLire une carte dans l’ordre : titre, orientation, légende, échelle et localisation. Une échelle permet d’estimer les distances réelles. Sur une frise chronologique, placer les dates dans l’ordre et distinguer passé ancien, passé récent et présent. Comparer des paysages ruraux et urbains.','Sur une carte, la légende explique les couleurs et les symboles.','À quoi sert la légende d’une carte ?',['À expliquer les symboles','À mesurer la température','À raconter une chanson'],0,'La légende donne le sens des signes de la carte.'),
    _Unit('T2 • Français','Grammaire et fonctions','Dans une phrase, le sujet commande l’accord du verbe. Le complément d’objet complète le verbe. L’adjectif qualificatif précise un nom et s’accorde avec lui.\n\nLe COD répond souvent à « qui ? » ou « quoi ? » après le verbe ; le COI répond à « à qui ? », « à quoi ? », « de qui ? » ou « de quoi ? ». L’adjectif s’accorde en genre et en nombre avec le nom. Transformer une phrase au pluriel aide à observer les accords.','Dans « Les jeunes élèves lisent un roman », élèves est sujet et roman est COD.','Quel est le sujet de « Les oiseaux construisent un nid » ?',['un nid','construisent','Les oiseaux'],2,'Les oiseaux accomplissent l’action : c’est le sujet.'),
    _Unit('T2 • Mathématiques','Fractions et nombres décimaux','Une fraction représente une partie d’une unité ou un quotient. Pour comparer des fractions de même dénominateur, je compare les numérateurs. Les décimaux permettent d’exprimer des mesures précises.\n\nReprésenter une fraction par un dessin partagé en parts égales. Pour des dénominateurs identiques, plus le numérateur est grand, plus la fraction est grande. Lire les dixièmes et centièmes, placer les nombres décimaux sur une droite et les utiliser dans les mesures de longueur et de monnaie.','3/8 est supérieur à 2/8 car 3 parts sont plus que 2 parts de même taille.','Laquelle est la plus grande ?',['2/7','5/7','1/7'],1,'Avec le même dénominateur, 5/7 est la plus grande.'),
    _Unit('T2 • Anglais','Questions au passé et vocabulaire','Le prétérit décrit une action terminée dans le passé. Les verbes réguliers prennent souvent -ed ; certains verbes sont irréguliers. Did sert à former une question au passé.\n\nApprendre quelques verbes irréguliers fréquents : go/went, see/saw, have/had, eat/ate. À la forme interrogative, utiliser Did + sujet + base verbale ; à la forme négative, didn’t + base verbale. Ajouter un repère de temps : yesterday, last week, two days ago.','Yesterday, I visited my grandmother. Did you play yesterday?','Quel mot aide à poser une question au passé ?',['Do','Did','Does'],1,'Did est utilisé pour les questions au prétérit.'),
    _Unit('T2 • Sciences','Mélanges, solutions et filtration','Une solution est un mélange homogène dans lequel un soluté se répartit dans un solvant. Une filtration sépare un solide non dissous d’un liquide, mais ne retire pas forcément les substances dissoutes.\n\nDistinguer dissolution et disparition : le sel dissous reste présent dans l’eau. On peut récupérer le sel par évaporation de l’eau, réalisée uniquement dans un cadre expérimental sécurisé. Identifier soluté, solvant et solution, puis décrire une méthode de séparation adaptée.','Le sel se dissout dans l’eau ; le sable ne s’y dissout pas.','Quel mélange est une solution ?',['Eau et sel dissous','Eau et sable','Eau et cailloux'],0,'Le sel dissous forme un mélange homogène avec l’eau.'),
    _Unit('T2 • Éducation sociale','Institutions et vie citoyenne','Les institutions organisent la vie collective et les services publics. Les citoyens respectent les règles, protègent les biens communs et peuvent participer à la vie de leur communauté.\n\nLes services publics répondent à des besoins collectifs comme l’éducation, la santé, la sécurité et les transports. Les règles s’appliquent à tous. Participer à la vie citoyenne signifie s’informer, dialoguer, respecter les différences et prendre soin des espaces communs.','Respecter un espace public et ne pas le dégrader est un acte citoyen.','Quel comportement est citoyen ?',['Détruire un panneau public','Respecter les règles communes','Jeter des déchets dans la rue'],1,'Respecter les règles et les biens communs favorise la vie collective.'),
    _Unit('T3 • Français','Conjugaison et production de textes','Le passé composé exprime souvent une action achevée. Il se forme avec avoir ou être au présent suivi du participe passé. Un texte argumentatif présente une idée et des raisons.\n\nAvec avoir, le participe passé ne s’accorde généralement pas avec le sujet dans les cas étudiés à ce niveau. Avec être, il s’accorde avec le sujet : elles sont arrivées. Pour argumenter, annoncer son opinion, donner deux raisons et illustrer chaque raison par un exemple.','Nous avons terminé le travail. Elles sont arrivées tôt.','Dans « Ils ont choisi », quel est l’auxiliaire ?',['être','avoir','choisi'],1,'Ont est une forme du verbe avoir.'),
    _Unit('T3 • Mathématiques','Mesures, périmètre et aire','Le périmètre mesure le contour d’une figure. L’aire mesure la surface. Pour un rectangle, P = 2 × (L + l) et A = L × l.\n\nToujours écrire l’unité : cm ou m pour un périmètre, cm² ou m² pour une aire. Pour un carré de côté c, P = 4c et A = c × c. Résoudre des problèmes en dessinant la figure, en relevant les dimensions et en vérifiant si la réponse est plausible.','Rectangle de 8 cm sur 3 cm : périmètre 22 cm et aire 24 cm².','Quelle est l’aire d’un rectangle de 6 cm sur 4 cm ?',['10 cm²','20 cm²','24 cm²'],2,'A = 6 × 4 = 24 cm².'),
    _Unit('T3 • Anglais','Futur et expression des projets','Will permet d’exprimer une décision ou une prédiction future. Going to sert souvent à parler d’un projet ou d’une intention déjà envisagée.\n\nFormer une phrase avec sujet + will + base verbale, ou sujet + am/is/are going to + base verbale. Utiliser tomorrow, next week et soon. Présenter un projet en deux ou trois phrases et écouter les projets des camarades.','I am going to visit my aunt tomorrow.','Quel mot indique le futur dans « I will help you » ?',['will','help','you'],0,'Will marque ici le futur.'),
    _Unit('T3 • Sciences','Électricité, énergie et sécurité','Un circuit fermé permet au courant de circuler. Un interrupteur ouvre ou ferme le circuit. L’énergie électrique peut être transformée en lumière, chaleur ou mouvement.\n\nIdentifier générateur, conducteurs, récepteur et interrupteur sur un schéma. Un circuit ouvert ne permet pas le passage du courant. Réaliser les expériences uniquement avec des piles et du matériel scolaire sécurisé ; ne jamais toucher aux installations du secteur.','Une ampoule transforme l’énergie électrique en énergie lumineuse et thermique.','Quel appareil transforme l’électricité en mouvement ?',['Un moteur','Un miroir','Un livre'],0,'Le moteur transforme l’énergie électrique en mouvement.'),
    _Unit('T3 • Éducation sociale','Environnement et préparation au CM2','La protection de l’environnement passe par la réduction des déchets, l’économie de l’eau, la préservation des sols et des arbres. Pour progresser, je sais expliquer mes réponses et organiser mon travail.\n\nTrier les déchets lorsque des dispositifs existent, réutiliser les objets et éviter les plastiques jetés dans la nature. Protéger les sols contre l’érosion par la couverture végétale. Pour préparer le CM2, organiser un planning de révision et s’entraîner à expliquer chaque démarche.','Un compost bien géré transforme certains déchets organiques en matière utile au sol.','Quel geste protège les ressources ?',['Gaspiller l’eau','Planter et protéger les arbres','Brûler les plastiques'],1,'Protéger les arbres aide à préserver les sols et la biodiversité.'),
 ];
 static int get unitCount=>_units.length;
 static int get lessonCount=>_units.length;
 static List<Exercise> assessmentExercisesForTerm(int term,{String? subjectName}){final prefix='T$term •';final result=<Exercise>[];for(var i=0;i<_units.length;i++){final u=_units[i];if(!u.title.startsWith(prefix))continue;if(subjectName!=null&&!_matches(u.title,subjectName))continue;result.add(Exercise(id:'cm1_t${term}_u${i}',lessonId:'cm1_t${term}_u${i}',question:u.question,options:u.options,correctIndex:u.answer,explanation:u.explanation));}return result;}
 static bool _matches(String title,String subject){final t=title.toLowerCase(),s=subject.toLowerCase();if(s.contains('français')||s.contains('francais'))return t.contains('français');if(s.contains('math'))return t.contains('mathématiques');if(s.contains('anglais')||s.contains('english'))return t.contains('anglais');if(s.contains('science'))return t.contains('sciences');if(s.contains('social')||s.contains('civique')||s.contains('morale')||s.contains('histoire')||s.contains('géographie'))return t.contains('éducation sociale');return false;}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Complément CM1 • Année complète')),body:ListView(padding:const EdgeInsets.all(16),children:[Card(child:Padding(padding:const EdgeInsets.all(16),child:Text('${Cm1CompletionScreen.unitCount} unités • ${Cm1CompletionScreen.lessonCount} leçons • 3 trimestres\nLis le cours, étudie l’exemple, réponds puis consulte la correction.',style:const TextStyle(fontWeight:FontWeight.w600)))),for(final u in _units)_UnitTile(unit:u)]));
}
class _Unit{final String title,objective,content,example,question;final List<String> options;final int answer;final String explanation;const _Unit(this.title,this.objective,this.content,this.example,this.question,this.options,this.answer,this.explanation);}
class _UnitTile extends StatefulWidget{final _Unit unit;const _UnitTile({required this.unit});@override State<_UnitTile> createState()=>_UnitTileState();}
class _UnitTileState extends State<_UnitTile>{int? choice;bool checked=false;@override Widget build(BuildContext context){final u=widget.unit;return Card(margin:const EdgeInsets.only(bottom:10),child:ExpansionTile(title:Text(u.title,style:const TextStyle(fontWeight:FontWeight.bold)),subtitle:Text(u.objective),children:[Padding(padding:const EdgeInsets.fromLTRB(16,0,16,16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(u.content),const SizedBox(height:8),Text('Exemple : ${u.example}',style:const TextStyle(fontStyle:FontStyle.italic)),const SizedBox(height:12),Text(u.question,style:const TextStyle(fontWeight:FontWeight.bold)),for(var i=0;i<u.options.length;i++)RadioListTile<int>(dense:true,contentPadding:EdgeInsets.zero,value:i,groupValue:choice,title:Text(u.options[i]),onChanged:checked?null:(v)=>setState(()=>choice=v)),FilledButton.tonal(onPressed:choice==null?null:()=>setState(()=>checked=true),child:const Text('Vérifier ma réponse')),if(checked)Text('${choice==u.answer?'Bonne réponse ! ':'À revoir. Bonne réponse : ${u.options[u.answer]}. '}${u.explanation}',style:TextStyle(fontWeight:FontWeight.w600,color:choice==u.answer?Colors.green.shade800:Theme.of(context).colorScheme.error)),if(checked)TextButton(onPressed:()=>setState((){choice=null;checked=false;}),child:const Text('Recommencer'))]))]));}}
